/// <summary>
///     The <c>AVAsmmContactPersonFrm_DirPartyRelationshipDS_Extension</c> class is the extension for <c>smmContactPerson</c>
/// </summary>
[ExtensionOf(formDataSourceStr(smmContactPerson, DirPartyRelationship))]
final class AVAsmmContactPersonFrm_DirPartyRelationshipDS_Extension
{
}

Method.Source:
/// <summary>
///    AVA <c>validateWrite</c> method.
/// </summary>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean validateWrite()
{
    boolean ret;

    DirPartyRelationship    locDirPartyRelationship;
    ContactPerson           locContactPerson;

    ret = next validateWrite();

    if (ret)
    {
        locDirPartyRelationship = element.dirPartyRelationship;
        locContactPerson        = element.ContactPerson;

        if (    locDirPartyRelationship.ParentParty    && locDirPartyRelationship.ChildParty
            &&  locDirPartyRelationship.ParentParty    != locContactPerson.Party
            &&  locDirPartyRelationship.ChildParty     != locContactPerson.Party                 )
        {
            // Relationship must have '%1-%2' as one of the parties.
            ret = checkFailed(strFmt("@SYS116469", locContactPerson.Party, locContactPerson.personName()));
        }
    }

    return ret;
}

/// <summary>
///    AVA <c>active</c> method.
/// </summary>
/// <returns>
///    <c>int</c> as return value
/// </returns>
public int active()
{
    int ret;

    FormRun                 formRun;
    FormDataSource          dirPartyRelationshipDS;
    DirPartyRelationship    locDirPartyRelationship;

    ret = next active();

    if (ret)
    {
        formRun                 = this.formRun();
        dirPartyRelationshipDS  = formRun.dataSource('DirPartyRelationship');
        locDirPartyRelationship = dirPartyRelationshipDS.cursor();

        element.getAllowedPartyTypes();
        dirPartyRelationshipDS.allowEdit(!locDirPartyRelationship.RecId ? true : false);
        dirPartyRelationshipDS.allowEdit(!locDirPartyRelationship.RecId ? true : false);
    }

    return ret;
}

/// <summary>
///    AVA <c>executeQuery</c> method.
/// </summary>
public void executeQuery()
{
    element.updateRange(element.dirPartyRelationship_ds);
    next executeQuery();
}

/// <summary>
///    AVA <c>init</c> method.
/// </summary>
public void init()
{
    next init();

    this.query().dataSourceTable(tableNum(DirPartyRelationship)).clearDynalinks();
    this.query().dataSourceTable(tableNum(DirPartyRelationship)).clearLinks();
}
